// Safeguard marker: INSTAOPS_V2_SCHEDULE — gates SCHEDULING_ENABLED + LIVE_PUBLISH_ENABLED before calling instaops_claim_due_scheduled_posts on Supabase instaops_posts.
function readCfg(key, fallback) {
  var blocked = false;
  try {
    if (typeof $vars !== 'undefined' && $vars && $vars[key] !== undefined && $vars[key] !== null && $vars[key] !== '') {
      return { value: String($vars[key]), blocked: false };
    }
  } catch (_) {}
  try {
    if (typeof $env !== 'undefined' && $env && $env[key] !== undefined && $env[key] !== null && $env[key] !== '') {
      return { value: String($env[key]), blocked: false };
    }
  } catch (_) { blocked = true; }
  return { value: fallback || '', blocked: blocked };
}

var schedEnabled = readCfg('SCHEDULING_ENABLED', 'false').value.toLowerCase() === 'true';
var livePubEnabled = readCfg('LIVE_PUBLISH_ENABLED', 'false').value.toLowerCase() === 'true';
var execId = String((typeof $execution !== 'undefined' && $execution && $execution.id) || Date.now());
return [{
  json: {
    enabled: schedEnabled && livePubEnabled,
    worker_id: 'w03:' + execId,
    sb_url: readCfg('SUPABASE_URL', 'https://cdgwdlhesgcxmswsamrj.supabase.co').value.replace(/\/$/, ''),
    n8n_url: readCfg('N8N_BASE_URL', 'https://137.23.61.127.sslip.io').value.replace(/\/$/, ''),
    default_ig_user_id: readCfg('INSTAGRAM_USER_ID', '17841453414532595').value
  }
}];

// Validates claimed SCHEDULED + LATER row (single or 2-10 CAROUSEL) with approved_revision === revision.
var cfg = $('CODE | Check Schedule Gate & Read Config').first().json;
var raw = $input.first().json || {};
var sc = raw.statusCode !== undefined ? Number(raw.statusCode) : (raw.error ? 0 : 200);
var body = raw.body !== undefined ? raw.body : raw;
var rows = !raw.error && sc < 300 && Array.isArray(body) ? body : [];
if (!rows.length) {
  return [{ json: { outcome: 'NONE' } }];
}
var row = rows[0];
var mediaType = String(row.media_type || 'REEL').toUpperCase();
var activeAssets = Array.isArray(row.media_items) ? row.media_items : [];
var rev = Number(row.revision || 0);
var appRev = Number(row.approved_revision || 0);
if (!rev || appRev !== rev || (mediaType === 'CAROUSEL' && (activeAssets.length < 2 || activeAssets.length > 10))) {
  return [{ json: { outcome: 'PRECHECK_FAIL', post_uuid: String(row.post_uuid), lock_key: String(row.lock_key), lock_owner: String(row.lock_owner), job_id: String(row.job_id || '') } }];
}
return [{
  json: {
    outcome: 'DISPATCH',
    post_uuid: String(row.post_uuid),
    post_id: String(row.post_id),
    lock_key: String(row.lock_key),
    lock_owner: String(row.lock_owner),
    job_id: String(row.job_id),
    request_id: String(row.request_id),
    dispatch_body: {
      action: 'PUBLISH',
      post_uuid: String(row.post_uuid),
      post_id: String(row.post_id),
      ig_user_id: String(row.ig_user_id || cfg.default_ig_user_id),
      media_type: mediaType,
      caption: String(row.caption || ''),
      media_url: String(row.media_url || ''),
      reviewed_revision: String(rev),
      approved_revision: String(appRev),
      confirm: true,
      lock_key: String(row.lock_key),
      lock_owner: String(row.lock_owner),
      job_id: String(row.job_id),
      request_id: String(row.request_id)
    }
  }
}];

var claimed = $('CODE | Validate Claimed Row & Build Dispatch').first().json;
var raw = $input.first().json || {};
var netErr = Boolean(raw.error && raw.statusCode === undefined);
var sc = raw.statusCode !== undefined ? Number(raw.statusCode) : (netErr ? 0 : 200);
var body = raw.body !== undefined ? raw.body : raw;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (_) { body = {}; } }
body = body || {};
if (!netErr && sc >= 200 && sc < 300 && body.accepted === true) {
  return [{ json: { status: 'ACCEPTED', post_uuid: claimed.post_uuid, post_id: claimed.post_id, execution_id: body.execution_id || '' } }];
}
if (!netErr && sc >= 400 && sc < 500) {
  return [{ json: { status: 'REJECTED_4XX', post_uuid: claimed.post_uuid, lock_key: claimed.lock_key, lock_owner: claimed.lock_owner, job_id: claimed.job_id, detail: JSON.stringify(body).slice(0, 300) } }];
}
var errDetail = netErr ? String(raw.error.message || 'timeout') : ('HTTP ' + sc);
return [{ json: { status: 'UNCERTAIN', post_uuid: claimed.post_uuid, job_id: claimed.job_id, detail: 'Uncertain scheduled W02 dispatch: ' + errDetail } }];
